use verus::prelude::*;

verus! {

    // calculate_loss returns the monetary loss given a non‐negative cost_price
    // and selling_price.  If cost_price > selling_price, loss = cost_price − selling_price;
    // otherwise loss = 0.
    fn calculate_loss(cost_price: i32, selling_price: i32) -> (loss: i32)
        requires
            // both prices are non‐negative
            cost_price >= 0,
            selling_price >= 0,
        ensures
            // postcondition matches the problem statement
            loss == if cost_price > selling_price {
                        cost_price - selling_price
                    } else {
                        0
                    }
    {
        if cost_price > selling_price {
            // we know cost_price > selling_price ≥ 0, so the difference is positive
            let diff: i32 = cost_price - selling_price;
            assert(diff > 0);        // supporting assertion for the verifier
            diff
        } else {
            0
        }
    }

}